steps.snippet:
location = binding["location"]
idx = device.find(hint="Type to search all", editable=True)
if idx is None:
    idx = device.find(text="Type to search all", editable=True)
if idx is None:
    idx = device.find(class_name="EditText", editable=True, clickable=True)
if idx is None:
    raise RuntimeError("OsmAnd search input field not found")
device.click(idx)
device.input_text(location, index=idx)

idx = device.find(text='INCREASE SEARCH RADIUS')
if idx is None:
    idx = device.find(contains='SEARCH RADIUS')
if idx is None:
    raise RuntimeError("'INCREASE SEARCH RADIUS' control not found on the no-results screen")
device.click(idx)

location = binding.get("location")
if not location:
    raise ValueError("binding['location'] is required but missing")

idx = device.find(hint="Type to search all", editable=True)
if idx is None:
    idx = device.find(text="Type to search all", editable=True)
if idx is None:
    raise LookupError("Search EditText (hint 'Type to search all') not found on screen")

device.input_text(location, index=idx)

app = binding.get("app_name", "OsmAnd")
for attempt in range(2):
    device.open_app(app)
    device.settle(3)
    if device.find(description="Configure map") is not None or device.find(description="Map") is not None:
        break
else:
    raise RuntimeError(f"OsmAnd map screen not detected after open_app({app!r}); app may not be installed or launch failed")

idx = device.find(hint='Type to search all', editable=True)
if idx is None:
    idx = device.find(text='Type to search all', editable=True)
if idx is None:
    raise RuntimeError("OsmAnd search field ('Type to search all') not found on screen")
device.input_text(binding['location'], index=idx)

idx = device.find(hint="Type to search all", editable=True)
if idx is None:
    idx = device.find(contains="search", editable=True)
if idx is None:
    idx = device.find(editable=True, clickable=True)
if idx is None:
    raise RuntimeError("OsmAnd search input field not found on screen")
device.input_text(binding["location"], index=idx)

idx = device.find(text='INCREASE SEARCH RADIUS')
if idx is None:
    idx = device.find(contains='INCREASE SEARCH RADIUS')
if idx is None:
    raise RuntimeError("Search-radius control ('INCREASE SEARCH RADIUS') not found on screen")
device.click(idx)

device.settle(1)
loc = str(binding["location"]).strip()
idx = device.find(text=loc, contains=True)
if idx is None:
    tokens = [t for t in loc.replace(",", " ").split() if t]
    for i, el in enumerate(device.elements()):
        txt = el.get("text") or ""
        if el.get("class_name") == "TextView" and tokens and all(t in txt for t in tokens):
            idx = i
            break
if idx is None:
    raise LookupError(f"No search-result TextView found for location {loc!r}")
device.click(idx)
